import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
// Warp-level sum reduction
__inline__ __device__ float warpReduceSum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}
// Pass 1: each row is split across multiple cooperating blocks (chunks) to
// increase grid-level parallelism when N (number of rows) is small but the
// row length L is large. Blocks accumulate partial sums via atomics and the
// last block to finish for a given row computes mean/invstd for that row.
template <int BLOCK_THREADS>
__global__ void layernorm_reduce_kernel(
    const float* __restrict__ X,
    float* __restrict__ sum_buf,
    float* __restrict__ sumsq_buf,
    int* __restrict__ counter_buf,
    float* __restrict__ mean_buf,
    float* __restrict__ invstd_buf,
    int N, int64_t L, float eps, int blocks_per_row)
{
    const int row = blockIdx.x / blocks_per_row;
    const int chunk = blockIdx.x % blocks_per_row;
    const int tid = threadIdx.x;
    const float* x_row_ptr = X + (int64_t)row * L;
    const int64_t L4 = L / 4;
    const int64_t rem_start = L4 * 4;
    const float4* __restrict__ x_row4 = reinterpret_cast<const float4*>(x_row_ptr);
    const int64_t quads_per_block = (L4 + blocks_per_row - 1) / blocks_per_row;
    const int64_t qstart = (int64_t)chunk * quads_per_block;
    int64_t qend = qstart + quads_per_block;
    if (qend > L4) qend = L4;
    float local_sum = 0.0f;
    float local_sumsq = 0.0f;
    int64_t i = qstart + tid;
    const int64_t unroll_stride4 = (int64_t)BLOCK_THREADS * 4;
    for (; i + (int64_t)3 * BLOCK_THREADS < qend; i += unroll_stride4) {
        float4 v0 = x_row4[i];
        float4 v1 = x_row4[i + BLOCK_THREADS];
        float4 v2 = x_row4[i + 2 * BLOCK_THREADS];
        float4 v3 = x_row4[i + 3 * BLOCK_THREADS];
        local_sum += v0.x + v0.y + v0.z + v0.w + v1.x + v1.y + v1.z + v1.w +
                     v2.x + v2.y + v2.z + v2.w + v3.x + v3.y + v3.z + v3.w;
        local_sumsq += v0.x * v0.x + v0.y * v0.y + v0.z * v0.z + v0.w * v0.w +
                       v1.x * v1.x + v1.y * v1.y + v1.z * v1.z + v1.w * v1.w +
                       v2.x * v2.x + v2.y * v2.y + v2.z * v2.z + v2.w * v2.w +
                       v3.x * v3.x + v3.y * v3.y + v3.z * v3.z + v3.w * v3.w;
    }
    const int64_t unroll_stride2 = (int64_t)BLOCK_THREADS * 2;
    for (; i + (int64_t)1 * BLOCK_THREADS < qend; i += unroll_stride2) {
        float4 v0 = x_row4[i];
        float4 v1 = x_row4[i + BLOCK_THREADS];
        local_sum += v0.x + v0.y + v0.z + v0.w + v1.x + v1.y + v1.z + v1.w;
        local_sumsq += v0.x * v0.x + v0.y * v0.y + v0.z * v0.z + v0.w * v0.w +
                       v1.x * v1.x + v1.y * v1.y + v1.z * v1.z + v1.w * v1.w;
    }
    for (; i < qend; i += BLOCK_THREADS) {
        float4 v4 = x_row4[i];
        local_sum += v4.x + v4.y + v4.z + v4.w;
        local_sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    // Only the last chunk handles the scalar tail (elements after the last full float4)
    if (chunk == blocks_per_row - 1) {
        for (int64_t i = rem_start + tid; i < L; i += BLOCK_THREADS) {
            float v = x_row_ptr[i];
            local_sum += v;
            local_sumsq += v * v;
        }
    }
    local_sum = warpReduceSum(local_sum);
    local_sumsq = warpReduceSum(local_sumsq);
    constexpr int NUM_WARPS = BLOCK_THREADS / 32;
    __shared__ float s_sum[NUM_WARPS];
    __shared__ float s_sumsq[NUM_WARPS];
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    if (lane_id == 0) {
        s_sum[warp_id] = local_sum;
        s_sumsq[warp_id] = local_sumsq;
    }
    __syncthreads();
    if (warp_id == 0) {
        float sum_val = (lane_id < NUM_WARPS) ? s_sum[lane_id] : 0.0f;
        float sumsq_val = (lane_id < NUM_WARPS) ? s_sumsq[lane_id] : 0.0f;
        sum_val = warpReduceSum(sum_val);
        sumsq_val = warpReduceSum(sumsq_val);
        if (lane_id == 0) {
            atomicAdd(&sum_buf[row], sum_val);
            atomicAdd(&sumsq_buf[row], sumsq_val);
            __threadfence();
            int prev = atomicAdd(&counter_buf[row], 1);
            if (prev == blocks_per_row - 1) {
                float total_sum = sum_buf[row];
                float total_sumsq = sumsq_buf[row];
                float mean = total_sum / (float)L;
                float var = total_sumsq / (float)L - mean * mean;
                var = fmaxf(var, 0.0f);
                mean_buf[row] = mean;
                invstd_buf[row] = rsqrtf(var + eps);
            }
        }
    }
}
// Pass 2: normalize using a grid-stride loop so we can launch many more blocks
// than N, keeping the SMs saturated even though N is small.
__global__ void layernorm_normalize_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Gamma,
    const float* __restrict__ Beta,
    float* __restrict__ Y,
    const float* __restrict__ mean_buf,
    const float* __restrict__ invstd_buf,
    int64_t N, int64_t L)
{
    const int64_t total = N * L;
    const int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += stride) {
        int64_t row = idx / L;
        int64_t col = idx - row * L;
        float mean = mean_buf[row];
        float invstd = invstd_buf[row];
        float v = X[idx];
        float g = Gamma[col];
        float b = Beta[col];
        Y[idx] = (v - mean) * invstd * g + b;
    }
}
// Vectorized normalize kernel used when L is divisible by 4 (common case),
// enabling coalesced float4 loads/stores for X/Y and reuse of vectorized
// gamma/beta loads.
__global__ void layernorm_normalize_kernel_vec4(
    const float4* __restrict__ X4,
    const float4* __restrict__ Gamma4,
    const float4* __restrict__ Beta4,
    float4* __restrict__ Y4,
    const float* __restrict__ mean_buf,
    const float* __restrict__ invstd_buf,
    int64_t N, int64_t L4)
{
    // Gamma/Beta only depend on the column index and are reused across all
    // N rows. Stage a tile of Gamma/Beta into shared memory once per
    // column-tile iteration and reuse it for every row, cutting global
    // memory traffic for the (typically small relative to X) weight
    // tensors by a factor of N. mean/invstd are per-row scalars re-read
    // from global memory for every column tile and every row by every
    // block; since N is typically small, cache them once in shared memory
    // for the entire kernel lifetime to eliminate this redundant traffic.
    extern __shared__ float4 s_mem[];
    float4* s_gamma = s_mem;
    float4* s_beta = s_mem + blockDim.x;
    float* s_mean = reinterpret_cast<float*>(s_beta + blockDim.x);
    float* s_invstd = s_mean + N;
    for (int64_t r = threadIdx.x; r < N; r += blockDim.x) {
        s_mean[r] = mean_buf[r];
        s_invstd[r] = invstd_buf[r];
    }
    __syncthreads();
    const int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (int64_t col4_base = (int64_t)blockIdx.x * blockDim.x; col4_base < L4; col4_base += stride) {
        int64_t col4 = col4_base + threadIdx.x;
        bool valid = col4 < L4;
        float4 g = make_float4(0.f, 0.f, 0.f, 0.f);
        float4 b = make_float4(0.f, 0.f, 0.f, 0.f);
        if (valid) {
            g = Gamma4[col4];
            b = Beta4[col4];
        }
        s_gamma[threadIdx.x] = g;
        s_beta[threadIdx.x] = b;
        __syncthreads();
        if (valid) {
            for (int64_t row = 0; row < N; ++row) {
                float mean = s_mean[row];
                float invstd = s_invstd[row];
                int64_t idx = row * L4 + col4;
                float4 v = X4[idx];
                float4 out;
                out.x = (v.x - mean) * invstd * g.x + b.x;
                out.y = (v.y - mean) * invstd * g.y + b.y;
                out.z = (v.z - mean) * invstd * g.z + b.z;
                out.w = (v.w - mean) * invstd * g.w + b.w;
                Y4[idx] = out;
            }
        }
        __syncthreads();
    }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be CUDA");
    TORCH_CHECK(beta.is_cuda(), "beta must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(gamma.scalar_type() == at::kFloat, "gamma must be float32");
    TORCH_CHECK(beta.scalar_type() == at::kFloat, "beta must be float32");
    auto x_c = x.contiguous();
    auto gamma_c = gamma.contiguous();
    auto beta_c = beta.contiguous();
    int64_t L = gamma_c.numel();
    TORCH_CHECK(x_c.numel() % L == 0, "x numel must be divisible by normalized_shape numel");
    int64_t N = x_c.numel() / L;
    auto y = torch::empty_like(x_c);
    auto opts_f = x_c.options();
    auto opts_i = x_c.options().dtype(at::kInt);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    // Combine sum_buf, sumsq_buf, counter_buf into a single contiguous
    // int32 buffer and zero it with a single cudaMemsetAsync call instead
    // of three separate ATen zero-fill kernel launches, reducing launch
    // overhead for these tiny (size-N) auxiliary buffers.
    auto combined_buf = torch::empty({3 * N}, opts_i);
    cudaMemsetAsync(combined_buf.data_ptr<int>(), 0, (size_t)(3 * N) * sizeof(int), stream);
    float* sum_ptr = reinterpret_cast<float*>(combined_buf.data_ptr<int>());
    float* sumsq_ptr = sum_ptr + N;
    int* counter_ptr = combined_buf.data_ptr<int>() + 2 * N;
    auto mean_buf = torch::empty({N}, opts_f);
    auto invstd_buf = torch::empty({N}, opts_f);
    constexpr int BLOCK_THREADS = 256;
    int64_t L4 = L / 4;
    int blocks_per_row = 128;
    if (L4 < (int64_t)blocks_per_row) {
        blocks_per_row = (int)std::max((int64_t)1, L4);
    }
    // Avoid a partial (tail) wave of thread blocks on pass 1: query the
    // device's SM count and the kernel's max resident blocks per SM to
    // determine the "wave size" (blocks that can run fully in parallel),
    // then round blocks_per_row up to the nearest value that makes the
    // total block count (N * blocks_per_row) a multiple of the wave size,
    // eliminating a costly partial wave at the tail of the grid.
    {
        int device = 0;
        cudaGetDevice(&device);
        cudaDeviceProp prop;
        cudaGetDeviceProperties(&prop, device);
        int max_blocks_per_sm = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(
            &max_blocks_per_sm, layernorm_reduce_kernel<BLOCK_THREADS>, BLOCK_THREADS, 0);
        long long wave_size = (long long)prop.multiProcessorCount * std::max(1, max_blocks_per_sm);
        if (wave_size > 0 && N > 0) {
            long long a = N, b = wave_size;
            while (b != 0) { long long t = b; b = a % b; a = t; }
            long long g = a > 0 ? a : 1;
            long long step = wave_size / g;
            if (step > 0) {
                long long rounded = ((long long)blocks_per_row + step - 1) / step * step;
                if (rounded < 1) rounded = 1;
                if (rounded <= L4) {
                    blocks_per_row = (int)rounded;
                } else if (L4 >= 1) {
                    blocks_per_row = (int)L4;
                }
            }
        }
    }
    dim3 block1(BLOCK_THREADS);
    dim3 grid1((unsigned)(N * blocks_per_row));
    layernorm_reduce_kernel<BLOCK_THREADS><<<grid1, block1, 0, stream>>>(
        x_c.data_ptr<float>(),
        sum_ptr,
        sumsq_ptr,
        counter_ptr,
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        (int)N, L, (float)eps, blocks_per_row
    );
    auto err1 = cudaGetLastError();
    TORCH_CHECK(err1 == cudaSuccess, "layernorm_reduce_kernel launch failed: ", cudaGetErrorString(err1));
    constexpr int BLOCK_THREADS2 = 256;
    bool can_vec4 = (L % 4 == 0) &&
        (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(gamma_c.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(beta_c.data_ptr<float>()) % 16 == 0);
    if (can_vec4) {
        int64_t L4v = L / 4;
        int64_t desired_blocks = (L4v + BLOCK_THREADS2 - 1) / BLOCK_THREADS2;
        if (desired_blocks > 65535) desired_blocks = 65535;
        if (desired_blocks < 1) desired_blocks = 1;
        dim3 block2(BLOCK_THREADS2);
        dim3 grid2((unsigned)desired_blocks);
        size_t smem_bytes = 2 * (size_t)BLOCK_THREADS2 * sizeof(float4) + 2 * (size_t)N * sizeof(float);
        layernorm_normalize_kernel_vec4<<<grid2, block2, smem_bytes, stream>>>(
            reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
            reinterpret_cast<const float4*>(gamma_c.data_ptr<float>()),
            reinterpret_cast<const float4*>(beta_c.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            mean_buf.data_ptr<float>(),
            invstd_buf.data_ptr<float>(),
            N, L4v
        );
    } else {
        int64_t total_elems = N * L;
        int64_t desired_blocks = (total_elems + BLOCK_THREADS2 - 1) / BLOCK_THREADS2;
        if (desired_blocks > 65535) desired_blocks = 65535;
        if (desired_blocks < 1) desired_blocks = 1;
        dim3 block2(BLOCK_THREADS2);
        dim3 grid2((unsigned)desired_blocks);
        layernorm_normalize_kernel<<<grid2, block2, 0, stream>>>(
            x_c.data_ptr<float>(),
            gamma_c.data_ptr<float>(),
            beta_c.data_ptr<float>(),
            y.data_ptr<float>(),
            mean_buf.data_ptr<float>(),
            invstd_buf.data_ptr<float>(),
            N, L
        );
    }
    auto err2 = cudaGetLastError();
    TORCH_CHECK(err2 == cudaSuccess, "layernorm_normalize_kernel launch failed: ", cudaGetErrorString(err2));
    return y;
}
"""
layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self, normalized_shape):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self._ext = layernorm_ext
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias.contiguous(),
            self.eps,
        )

