    float local_sumsq = 0.0f;
    int64_t i = qstart + tid;
    const int64_t unroll_stride = (int64_t)BLOCK_THREADS * 2;
    for (; i + (int64_t)1 * BLOCK_THREADS < qend; i += unroll_stride) {
        float4 v0 = x_row4[i];
        float4 v1 = x_row4[i + BLOCK_THREADS];
        local_sum += v0.x + v0.y + v0.z + v0.w + v1.x + v1.y + v1.z + v1.w;
        local_sumsq += v0.x * v0.x + v0.y * v0.y + v0.z * v0.z + v0.w * v0.w +
                       v1.x * v1.x + v1.y * v1.y + v1.z * v1.z + v1.w * v1.w;
    }
    for (; i < qend; i += BLOCK_THREADS) {
